/**
 * The public incremental fold (r1-fixes 5.1, D20, D21): the CLI's own fold,
 * retained between calls as a VERSIONED snapshot, so a consumer that holds
 * one applies the tail instead of replaying the stream — cloud ingest per
 * append, the Mac app per refresh, without a process spawn or a full fold.
 *
 * Laws (D20's rule): a snapshot is DERIVED state. It is not an event and
 * never validates as one, the engine never writes it under .sofar/, and
 * export, import and sync never carry it. Its version — the engine version
 * and a hash of the schema — is a readable field, and a mismatch on parse is
 * a refusal with both versions in it (D21): the consumer refolds, and can
 * count why. Nothing here reads the clock or the environment: every
 * timestamp in the folded state comes from an event.
 *
 * Exactness is the 2.7 checkpoint's: `fold` applies the tail through the
 * same loop body the CLI uses, and refuses — with a reason — any tail the
 * fast path cannot prove equal to a full fold: an id below the cursor, a
 * correction, an envelope the decoder rejects. A refusal means "refold from
 * all events", never "close enough".
 */

/** The snapshot's version: both halves readable, both compared on parse. */
export interface SnapshotVersion {
  engine: string
  /** sha256 over the schema package version, EVENT_TYPES and every type's reference fields. */
  schema: string
}

export interface Snapshot {
  version: SnapshotVersion
  /** Greatest event id folded — the cursor a since-read continues from ('' on an empty fold). */
  cursor: string
  /** Lines consumed, so an appended line gets the number a full fold gives it. */
  lines: number
  slug: string
  /** The retained replay. Opaque to consumers; `stateOf` reads it. */
  checkpoint: FoldCheckpoint
}

export type FoldRefusal = 'version' | 'order' | 'correction' | 'invalid'

export type FoldStep = { ok: true; snapshot: Snapshot } | { ok: false; reason: FoldRefusal; detail: string }

export type ParsedSnapshot =
  | { ok: true; snapshot: Snapshot }
  | { ok: false; reason: 'version'; found: SnapshotVersion; expected: SnapshotVersion }
  | { ok: false; reason: 'corrupt'; detail: string }

let schemaHash: string | undefined
/** Computed once per process from the schema itself, so a shape change cannot leave it stale. */
export function currentSchemaHash(): string {
  if (schemaHash !== undefined) return schemaHash
  const h = createHash('sha256')
  h.update(`${SCHEMA_VERSION}\n`)
  for (const type of EVENT_TYPES) h.update(`${type}:${EVENT_TYPE_REFERENCE[type].fields}\n`)
  schemaHash = h.digest('hex')
  return schemaHash
}

export function currentVersion(): SnapshotVersion {
  return { engine: ENGINE_VERSION, schema: currentSchemaHash() }
}

function toLines(input: readonly EventEnvelope[] | readonly string[]): string[] {
  const lines: string[] = []
  for (const item of input) lines.push(typeof item === 'string' ? item : serializeEvent(item))
  lines.push('') // the trailing newline a file ends with, so line numbers match a file read
  return lines
}

/** The full fold, retained: what every incremental step starts from. */
export function foldAll(input: readonly EventEnvelope[] | readonly string[], slug = ''): Snapshot {
  const lines = toLines(input)
  const checkpoint = replayDecoded(decodeLines(lines), slug, countLines(lines))
  return { version: currentVersion(), cursor: checkpoint.lastId, lines: checkpoint.lineCount, slug, checkpoint }
}

/** Deep copy of a checkpoint: `fold` never mutates the snapshot it was given. */
function cloneCheckpoint(cp: FoldCheckpoint): FoldCheckpoint {
  return {
    slug: cp.slug,
    state: structuredClone(cp.state),
    warnings: cp.warnings.slice(),
    voided: new Set(cp.voided),
    blockNotes: new Map(cp.blockNotes),
    edges: cp.edges.slice(),
    seenSessions: new Set(cp.seenSessions),
    orphanCandidates: cp.orphanCandidates.map((o) => ({ ...o })),
    guardCache: new Map(cp.guardCache),
