export function fold(snapshot: Snapshot, events: readonly EventEnvelope[] | readonly string[]): FoldStep {
  const expected = currentVersion()
  if (snapshot.version.engine !== expected.engine || snapshot.version.schema !== expected.schema) {
    return { ok: false, reason: 'version', detail: `snapshot is ${snapshot.version.engine}/${snapshot.version.schema.slice(0, 12)}, this engine is ${expected.engine}/${expected.schema.slice(0, 12)}` }
