    } catch {
      return { ok: false, reason: 'invalid', detail: 'a tail line is not JSON' }
    }
    const check = validateEnvelope(decoded)
    if (!check.ok) return { ok: false, reason: 'invalid', detail: `a tail line is not an envelope: ${check.errors.map((e) => `${e.field}: ${e.message}`).join('; ')}` }
