/** Quote-aware split on the shell's sequencing operators — inside quotes an `&&` is text. */
function splitSegments(cmd: string): string[] {
  const out: string[] = []
  let cur = ''
  let quote: string | null = null
  for (let i = 0; i < cmd.length; i += 1) {
    const ch = cmd[i]!
    if (quote !== null) {
      cur += ch
      if (ch === quote) quote = null
      else if (ch === '\\' && quote === '"') {
        cur += cmd[i + 1] ?? ''
        i += 1
      }
      continue
    }
    if (ch === '"' || ch === "'") {
      quote = ch
      cur += ch
    } else if (ch === '\\') {
      cur += ch + (cmd[i + 1] ?? '')
      i += 1
    } else if ((ch === '&' || ch === '|') && cmd[i + 1] === ch) {
      out.push(cur)
      cur = ''
      i += 1
    } else if (ch === ';' || ch === '|' || ch === '\n') {
      out.push(cur)
      cur = ''
    } else cur += ch
  }
  out.push(cur)
  return out
