// Every design must honor the MemorySystem contract on a tiny scripted story.
import { describe, expect, it } from 'vitest'
import { contextText } from '../src/core/text.ts'
import { DAY, type MemEvent } from '../src/core/types.ts'
import { ABLATIONS, DESIGNS } from '../src/designs/registry.ts'

const story: MemEvent[] = [
  { id: 'e1', t: 0, role: 'user', text: 'I live in Pune.' },
  { id: 'e2', t: 1, role: 'user', text: 'My phone number is +49 151 2345 6789.' },
  { id: 'e3', t: 2, role: 'assistant', text: 'Noted — +49 151 2345 6789.' },
  { id: 'e4', t: DAY, role: 'user', text: 'Can you help me fix this regex?' },
]
const ask = (sys: ReturnType<(typeof DESIGNS)['A']>, q: string) => contextText(sys.recall(q, 2 * DAY, 256))

describe.each(Object.entries({ ...DESIGNS, ...ABLATIONS }))('%s', (_name, make) => {
  it('recalls a stated fact', () => {
    const sys = make()
    story.forEach((e) => sys.write(e))
    expect(ask(sys, 'Where do I live now?')).toContain('Pune')
  })

  it('forgetting removes the fact from recall', () => {
    const sys = make()
    story.forEach((e) => sys.write(e))
    sys.forget('my phone number', DAY)
    expect(ask(sys, 'What is my phone number?')).not.toContain('2345 6789')
  })

  it('export → import preserves recall', () => {
    const sys = make()
    story.forEach((e) => sys.write(e))
    const fresh = make()
    fresh.importState(sys.exportState())
    expect(ask(fresh, 'Where do I live now?')).toBe(ask(sys, 'Where do I live now?'))
  })
})

describe('G deletion reaches every copy', () => {
  it('shreds backups and echoed copies', () => {
    const sys = DESIGNS.G!()
    story.forEach((e) => sys.write(e))
    const backup = sys.backup()
    expect(sys.forensicRead(backup)).toContain('2345 6789')
    sys.forget('my phone number', DAY)
    expect(sys.forensicRead(backup)).not.toContain('2345 6789')
    expect(sys.forensicDump()).not.toContain('2345 6789')
  })
})
