// Local LLM arms via Ollama chat: a message TAGGER (topic + subject) and a
// READER (answers a question from a design's context). Temperature 0,
// thinking off, JSON-schema output; results cached under .cache/.

import { createHash } from 'node:crypto'
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import type { Backend } from '../core/text.ts'

const HOST = process.env.OLLAMA_HOST ?? 'http://127.0.0.1:11434'
const PARALLEL = Number(process.env.LLM_PARALLEL ?? 4)

async function chat(model: string, system: string, user: string, format?: object): Promise<string> {
  const r = await fetch(`${HOST}/api/chat`, {
    method: 'POST',
    body: JSON.stringify({ model, stream: false, think: false, format, options: { temperature: 0, seed: 1 }, messages: [{ role: 'system', content: system }, { role: 'user', content: user }] }),
  })
  if (!r.ok) throw new Error(`ollama ${model}: HTTP ${r.status} ${await r.text()}`)
  return ((await r.json()) as { message: { content: string } }).message.content.trim()
}

/** Run `f` over `xs` with bounded concurrency, reporting progress. */
async function pool<T, R>(label: string, xs: T[], f: (x: T) => Promise<R>): Promise<R[]> {
  const out: R[] = new Array(xs.length)
  let next = 0
  let done = 0
  const t0 = Date.now()
  await Promise.all(
    Array.from({ length: Math.min(PARALLEL, xs.length) }, async () => {
      while (next < xs.length) {
        const i = next++
        out[i] = await f(xs[i]!)
        if (++done % 25 === 0 || done === xs.length) process.stderr.write(`\r  ${label}: ${done}/${xs.length} (${((Date.now() - t0) / 1000).toFixed(0)}s)`)
      }
    }),
  )
  if (xs.length) process.stderr.write('\n')
  return out
}

class JsonCache<V> {
  private path: string
  private data: Record<string, V>
  constructor(name: string) {
    mkdirSync('.cache', { recursive: true })
    this.path = `.cache/${name.replace(/[^\w.-]/g, '_')}.json`
    this.data = existsSync(this.path) ? JSON.parse(readFileSync(this.path, 'utf8')) : {}
  }
  get = (k: string) => this.data[k]
  set = (k: string, v: V) => void (this.data[k] = v)
  save = () => writeFileSync(this.path, JSON.stringify(this.data))
}

// ---- tagger ----------------------------------------------------------------

const SLOTS = ['residence', 'work', 'pet', 'lang', 'partner', 'phone', 'editor', 'none'] as const
const SUBJECTS = ['user', 'sister', 'other', 'none'] as const
type Tag = { slot: (typeof SLOTS)[number]; subject: (typeof SUBJECTS)[number] }

const TAG_SYSTEM = `You label messages from a chat between a user and an AI assistant, for a personal-memory system.
Return JSON {"slot": ..., "subject": ...}.
slot — which personal-profile topic the message states or asks about:
  residence (city/home where someone lives), work (employer/company/job), pet (a pet and its name),
  lang (favorite/main programming language), partner (romantic partner), phone (phone number / how to contact),
  editor (code editor or IDE), none (anything else, including general tasks and small talk).
subject — whose personal fact the message states:
  user (the user themself), sister (the user's sister), other (someone else, e.g. a neighbor or colleague, or a place/thing merely mentioned),
  none (no personal fact is stated: questions, requests, assistant replies).`

const TAG_SCHEMA = {
  type: 'object',
  properties: { slot: { type: 'string', enum: SLOTS }, subject: { type: 'string', enum: SUBJECTS } },
  required: ['slot', 'subject'],
}

/** Wrap an embedding backend so topic + subject come from an LLM tagger. */
export async function withTagger(base: Backend, model: string, texts: string[]): Promise<Backend> {
  const cache = new JsonCache<Tag>(`tag-${model}`)
  const todo = [...new Set(texts)].filter((t) => !cache.get(t))
  await pool(`${model} tagging`, todo, async (t) => {
    cache.set(t, JSON.parse(await chat(model, TAG_SYSTEM, t, TAG_SCHEMA)) as Tag)
  })
  cache.save()
  const tag = (t: string) => {
    const x = cache.get(t)
    if (!x) throw new Error(`untagged text ${JSON.stringify(t)}`)
    return x
  }
  return {
    name: `${base.name}+${model}`,
    embed: base.embed,
    slot: (t) => (tag(t).slot === 'none' ? null : tag(t).slot),
    subject: (t) => tag(t).subject,
  }
}

// ---- reader ----------------------------------------------------------------

const READ_SYSTEM = `You are an assistant with a memory of past conversations with the user.
Answer the user's question using ONLY the memory lines provided. Each line starts with the day it was recorded; later days override earlier ones.
Reply with just the answer (a name, place, number, or short phrase). If the memory does not contain the answer, reply exactly: UNKNOWN`

export class Reader {
  private cache: JsonCache<string>
  model: string
  constructor(model: string) {
    this.model = model
    this.cache = new JsonCache<string>(`read-${model}`)
  }
  private key = (q: string, ctx: string) => createHash('sha256').update(q + '\u0000' + ctx).digest('hex')
  async answerAll(jobs: { q: string; ctx: string }[]): Promise<string[]> {
    const todo = [...new Map(jobs.filter((j) => !this.cache.get(this.key(j.q, j.ctx))).map((j) => [this.key(j.q, j.ctx), j])).values()]
    await pool(`${this.model} reading`, todo, async (j) => {
      const ans = await chat(this.model, READ_SYSTEM, `Memory:\n${j.ctx || '(empty)'}\n\nQuestion: ${j.q}`)
      this.cache.set(this.key(j.q, j.ctx), ans)
    })
    this.cache.save()
    return jobs.map((j) => this.cache.get(this.key(j.q, j.ctx))!)
  }
}
