// LC — Long-context baseline: no memory design at all. The whole transcript,
// oldest first, up to the reader's context window. The competitor every
// memory system must beat: "just give the model everything".
// Budget is fixed by the window, not the benchmark's per-question budget.

import { fitBudget } from '../core/text.ts'
import type { MemEvent, MemorySystem } from '../core/types.ts'

export const LC_WINDOW = Number(process.env.LC_WINDOW ?? 36000) // tokens; qwen3:14b holds 40,960

export function createLongContext(window = LC_WINDOW): MemorySystem {
  let log: MemEvent[] = []
  const dump = () => JSON.stringify(log)
  return {
    name: 'LC-longcontext',
    write(e) {
      log.push(e)
    },
    recall() {
      // keep the most recent that fit, then present oldest-first
      const recent = fitBudget([...log].reverse().map((e) => ({ text: e.text, t: e.t })), window)
      return recent.reverse()
    },
    forget() {}, // a raw transcript has no forget: the realistic long-context setup
    exportState: dump,
    importState(s) {
      log = JSON.parse(s)
    },
    backup: dump,
    forensicRead: (b) => b,
    forensicDump: dump,
    storedBytes: () => dump().length,
  }
}
